TOOL_BY_ID = {row["tool_id"]: row for row in TOOL_CATALOG}
TOOL_BY_NAME = {row["canonical_name"].casefold(): row for row in TOOL_CATALOG}
IMPLEMENTED_TOOL_IDS = frozenset(["T011","T013","T014","T016","T019","T021","T022","T023","T026","T032","T042","T055","T072","T078","T081"])


def get_tool(tool_id: str) -> dict | None:
    """Return a defensive copy of a canonical tool record."""
    row = TOOL_BY_ID.get(str(tool_id or "").strip().upper())
    return dict(row) if row else None


def find_tool(value: str) -> dict | None:
    """Resolve a canonical name without granting access through its display label."""
    row = TOOL_BY_NAME.get(str(value or "").strip().casefold())
    return dict(row) if row else None


def tool_access_allowed(tool_id: str, tier: str) -> bool:
    """Fail closed for unknown IDs and enforce the catalog minimum tier."""
    row = TOOL_BY_ID.get(str(tool_id or "").strip().upper())
    if row is None:
        return False
    try:
        from shoir_tier_capabilities import tier_allows
        return bool(tier_allows(tier, row["target_minimum_tier"]))
    except Exception:
        # Entitlement uncertainty must never grant protected access.
        return False


def tool_is_actionable(tool_id: str) -> bool:
    """True only for an implemented deterministic action, not for a catalog row."""
    key = str(tool_id or "").strip().upper()
    row = TOOL_BY_ID.get(key)
    return bool(
        row
        and key in IMPLEMENTED_TOOL_IDS
        and row.get("implementation_status") in {
            "IMPLEMENTED_NEEDS_VALIDATION", "VERIFIED_WORKING"
        }
    )


def catalog_integrity_errors() -> list[str]:
    errors: list[str] = []
    if len(TOOL_CATALOG) != 100:
        errors.append(f"expected 100 catalog rows, found {len(TOOL_CATALOG)}")
    ids = [str(row.get("tool_id", "")) for row in TOOL_CATALOG]
    if len(ids) != len(set(ids)):
        errors.append("duplicate tool IDs")
    for row in TOOL_CATALOG:
        if row.get("tool_id") not in {f"T{i:03d}" for i in range(1, 101)}:
            errors.append(f"invalid stable ID: {row.get('tool_id')}")
        if row.get("implementation_status") not in STATUS_VALUES:
            errors.append(f"invalid status for {row.get('tool_id')}")
        if row.get("target_minimum_tier") not in {
            "Starter", "Mid-Tier Pro", "Professional", "Enterprise",
            "Enterprise Plus", "Research Pack"
        }:
            errors.append(f"invalid minimum tier for {row.get('tool_id')}")
    return errors
